      "line": 10,
      "startLine": 10,
      "side": "RIGHT",
      "comment": "outputs/pr_review_comments/comment1.md",
      "severity": "SUGGESTION"
    },
    {
      "path": ".github/workflows/quality.yml",
      "line": 114,
      "startLine": 114,
      "side": "RIGHT",
      "comment": "outputs/pr_review_comments/comment2.md",
      "severity": "SUGGESTION"
    }
  ],
  "issueCounts": {
