arguments.command:
git --no-pager diff 28846901...HEAD --unified=0 -- .github/workflows/quality.yml | awk '
/^\+\+\+/ {next}
/^@@/ {split($3,a,","); newstart=substr(a[1],2); newoff=0; next}
/^\+/ {line=newstart+newoff; if (line==10 || line==114) printf "ADDED line %d: %s\n", line, substr($0,2,80); newoff++; next}
/^-/ {next}
/^ / {newoff++}
'; echo "---"; sed -n '10p;114p' .github/workflows/quality.yml

